// Des: Unit tests for job registry and output ring
// Flo: add or remove jobs > append ring lines > assert counts, offsets, leases
// I/O: fake ids, dummy Child, NDJSON lines > pass or fail
// ===================================================================
const std = @import("std"); const regi = @import("ru-jobz-regi.zig"); const tszz = std.testing;
test "liveCoun tracks add and remove, ending at zero" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); var chil: std.process.Child = undefined; chil.stdin = null; try tszz.expectEqual(@as(?usize, 0), reg.liveCoun(iozz)); try reg.addz(iozz, "a", .{ .chil = &chil }); try reg.addz(iozz, "b", .{ .chil = &chil }); try tszz.expectEqual(@as(?usize, 2), reg.liveCoun(iozz)); reg.remo(iozz, "a"); reg.remo(iozz, "b"); try tszz.expectEqual(@as(?usize, 0), reg.liveCoun(iozz)); }
test "remove of an unknown id is a no-op" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); reg.remo(iozz, "never-added"); try tszz.expectEqual(@as(?usize, 0), reg.liveCoun(iozz)); }
test "add twice under one id keeps a single entry" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); var chil: std.process.Child = undefined; chil.stdin = null; try reg.addz(iozz, "dup", .{ .chil = &chil }); try reg.addz(iozz, "dup", .{ .chil = &chil }); try tszz.expectEqual(@as(?usize, 1), reg.liveCoun(iozz)); reg.remo(iozz, "dup"); try tszz.expectEqual(@as(?usize, 0), reg.liveCoun(iozz)); }
test "ring appends, replays by offset, drops oldest lines past CAP" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const ring = try regi.Ring.crea(tszz.allocator, "cmd", "cwd", "tab", 0); defer ring.rele(); ring.appe(iozz, "{\"a\":1}\n"); ring.appe(iozz, "{\"b\":2}\n"); var outz: [64]u8 = undefined; const firs = ring.fromRead(iozz, 0, &outz); try tszz.expectEqualStrings("{\"a\":1}\n{\"b\":2}\n", outz[0..firs.byte]); try tszz.expect(!firs.lost and !firs.done); try tszz.expectEqual(@as(usize, 0), ring.fromRead(iozz, firs.next, &outz).byte); ring.fini(iozz); try tszz.expect(ring.fromRead(iozz, firs.next, &outz).done); const line = ("x" ** 1022) ++ "\n"; var indx: usize = 0; while (indx < regi.Ring.CAPZ / 1023 + 8) : (indx += 1) ring.appe(iozz, line); try tszz.expect(ring.size(iozz) > regi.Ring.CAPZ / 2); const late = ring.fromRead(iozz, 0, &outz); try tszz.expect(late.lost); try tszz.expect(ring.base > 0 and (ring.base - 16) % 1023 == 0); try tszz.expectEqual(@as(u8, 'x'), outz[0]); }
test "stdin lease refuses after retire; keep flag round-trips" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); var chil: std.process.Child = undefined; chil.stdin = null; try reg.addz(iozz, "j", .{ .chil = &chil }); try tszz.expect(reg.stdiAcqu(iozz, "j") == null); reg.stdiReti(iozz, "j"); try tszz.expect(reg.stdiAcqu(iozz, "j") == null); try tszz.expect(reg.keepSetz(iozz, "j", true)); try tszz.expect(!reg.keepSetz(iozz, "nope", true)); reg.remo(iozz, "j"); }
test "pausSetz answers none, done and same without touching a process" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); var chil: std.process.Child = undefined; chil.stdin = null; try tszz.expectEqual(regi.PausCode.none, reg.pausSetz(iozz, "nope", true, 0)); try reg.addz(iozz, "j", .{ .chil = &chil }); try tszz.expectEqual(regi.PausCode.same, reg.pausSetz(iozz, "j", false, 5)); try tszz.expectEqual(@as(i64, 0), reg.pausTota(iozz, "j", 99)); reg.doneMark(iozz, "j"); try tszz.expectEqual(regi.PausCode.done, reg.pausSetz(iozz, "j", true, 5)); try tszz.expectEqual(@as(i64, 0), reg.pausTota(iozz, "nope", 5)); }
test "pausSetz fails cleanly when there is nothing to freeze, and the pause clock only counts paused time" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; defer reg.dein(tszz.allocator); var chil: std.process.Child = undefined; chil.stdin = null; chil.id = null; try reg.addz(iozz, "j", .{ .chil = &chil }); try tszz.expectEqual(regi.PausCode.fail, reg.pausSetz(iozz, "j", true, 10)); try tszz.expectEqual(@as(i64, 0), reg.pausTota(iozz, "j", 50)); if (reg.mapz.getPtr("j")) |entr| { entr.paus = true; entr.paus_star = 100; entr.paus_tota = 7; } try tszz.expectEqual(@as(i64, 7 + 30), reg.pausTota(iozz, "j", 130)); }
